p=Path('/home/ubuntu/diabetes-care-ar/client/src/pages/Home.tsx')
s=p.read_text()
s=s.replace('  AlarmClock,\n', '  AlarmClock,\n  Trophy,\n  Flame,\n  HeartPulse,\n  Brain,\n')
s=s.replace('const [profile, setProfile] = useState(() => {\n    try { return JSON.parse(localStorage.getItem("diabetes-profile") || "null") || { age: 42, height: 168, weight: 69, type: "النوع الثاني" }; } catch { return { age: 42, height: 168, weight: 69, type: "النوع الثاني" }; }\n  });', 'const [profile, setProfile] = useState(() => {\n    try { return JSON.parse(localStorage.getItem("diabetes-profile") || "null") || { age: 42, height: 168, weight: 69, type: "النوع الثاني", gender: "أنثى", bloodType: "غير معروف", conditions: [], routines: [], activity: "متوسط" }; } catch { return { age: 42, height: 168, weight: 69, type: "النوع الثاني", gender: "أنثى", bloodType: "غير معروف", conditions: [], routines: [], activity: "متوسط" }; }\n  });')
s=s.replace('  const [foodLoading, setFoodLoading] = useState(false);', '  const [foodLoading, setFoodLoading] = useState(false);\n  const [nutrition, setNutrition] = useState(() => JSON.parse(localStorage.getItem("diabetes-nutrition") || "null") || { calories: 0, carbohydrates: 0, protein: 0, meals: 0 });\n  const [healthResult, setHealthResult] = useState("");\n  const [healthLoading, setHealthLoading] = useState(false);')
s=s.replace('  const dailyMutation = trpc.ai.dailyAnalysis.useMutation();', '  const dailyMutation = trpc.ai.dailyAnalysis.useMutation();\n  const healthMutation = trpc.ai.healthAnalysis.useMutation();')
s=s.replace('  useEffect(() => { localStorage.setItem("diabetes-settings", JSON.stringify(settings)); }, [settings]);', '  useEffect(() => { localStorage.setItem("diabetes-settings", JSON.stringify(settings)); }, [settings]);\n  useEffect(() => { localStorage.setItem("diabetes-nutrition", JSON.stringify(nutrition)); }, [nutrition]);')
s=s.replace('      setFoodResult(result.answer);', '      setFoodResult(result.answer);\n      if (result.nutrition) setNutrition(current => ({ calories: current.calories + Number(result.nutrition.calories || 0), carbohydrates: current.carbohydrates + Number(result.nutrition.carbohydrates || 0), protein: current.protein + Number(result.nutrition.protein || 0), meals: current.meals + 1 }));')
s=s.replace('  function saveProfile() {', '  async function runHealthAnalysis() {\n    setHealthLoading(true);\n    try {\n      const result = await healthMutation.mutateAsync({ profile: { age: Number(profile.age), height: Number(profile.height), weight: Number(profile.weight), gender: profile.gender, bloodType: profile.bloodType, activity: profile.activity }, conditions: profile.conditions || [], routines: profile.routines || [], goals: "تحسين السكر واللياقة مع روتين يومي واقعي" });\n      setHealthResult(result.answer);\n    } catch { setHealthResult("تعذر تحليل الملف الصحي حالياً. احفظ بياناتك وجرّب مرة أخرى لاحقاً."); }\n    finally { setHealthLoading(false); }\n  }\n\n  function saveProfile() {')
s=s.replace('<SettingsSection settings={settings} setSettings={setSettings} water={water} setWater={setWater} onLogin={() => startLogin()} onExport={exportPdf} />', '<SettingsSection settings={settings} setSettings={setSettings} water={water} setWater={setWater} profile={profile} setProfile={setProfile} healthResult={healthResult} healthLoading={healthLoading} onHealthAnalysis={runHealthAnalysis} nutrition={nutrition} onLogin={() => startLogin()} onExport={exportPdf} />')
s=s.replace('<FoodSection foodImage={foodImage} foodResult={foodResult} foodLoading={foodLoading} fileRef={fileRef} onFoodChange={onFoodChange} />', '<FoodSection foodImage={foodImage} foodResult={foodResult} foodLoading={foodLoading} fileRef={fileRef} onFoodChange={onFoodChange} nutrition={nutrition} />')
start=s.index('function FoodSection(')
end=s.index('\nfunction MovementSection', start)
food='''function FoodSection({ foodImage, foodResult, foodLoading, fileRef, onFoodChange, nutrition }: any) { return <div className="fade-up"><SectionTitle eyebrow="دليل يومي" title="الأطعمة بوضوح" detail="صوّر وجبتك وتابع السعرات والكربوهيدرات المقدّرة خلال اليوم" action={<button onClick={() => fileRef.current?.click()} className="flex items-center gap-2 rounded-[14px] bg-[#0e7772] px-4 py-2.5 text-xs font-extrabold text-white"><Camera size={15} /> حلّل طبقاً</button>} /><div className="mb-6 grid gap-4 sm:grid-cols-3"><NutritionMetric label="السعرات المقدّرة" value={nutrition.calories} unit="kcal" icon={Flame} color="#f5b85f" /><NutritionMetric label="الكربوهيدرات" value={nutrition.carbohydrates} unit="غ" icon={Zap} color="#74e1c6" /><NutritionMetric label="وجبات مصوّرة" value={nutrition.meals} unit="وجبة" icon={Camera} color="#b9a4ff" /></div><input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={onFoodChange} /><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="glass-dark relative overflow-hidden p-6 text-white"><div className="mb-3 flex items-center gap-2 text-[#a9ebdb]"><Sparkles size={17} /><span className="text-xs font-bold">تحليل الطعام بالذكاء الاصطناعي</span></div><h3 className="text-xl font-extrabold leading-8">صوّر الطبق،<br />وسنقدّر محتواه ونقترح بدائل.</h3><p className="mt-3 max-w-sm text-xs leading-6 text-white/60">التقديرات تقريبية للتثقيف، وقد تختلف حسب الكمية وطريقة التحضير.</p><button onClick={() => fileRef.current?.click()} className="mt-5 rounded-[13px] bg-white px-4 py-2.5 text-xs font-extrabold text-[#0e7772]"><Camera size={15} className="ml-1 inline" /> اختر صورة</button></div><div className="glass overflow-hidden p-5">{foodImage ? <div className="grid gap-4 sm:grid-cols-[130px_1fr]"><img src={foodImage} alt="الطبق" className="h-32 w-full rounded-[15px] object-cover" /><div><div className="mb-2 flex items-center gap-2 text-xs font-extrabold text-[#dcefee]"><Bot size={16} className="text-[#74e1c6]" /> التقييم والبدائل والوصفات</div>{foodLoading ? <div className="space-y-2"><div className="h-3 animate-pulse rounded-full bg-white/10" /><div className="h-3 w-5/6 animate-pulse rounded-full bg-white/10" /></div> : <p className="max-h-52 overflow-auto whitespace-pre-wrap text-[11px] leading-6 text-slate-300">{foodResult}</p>}</div></div> : <div className="flex min-h-[150px] flex-col items-center justify-center text-center"><Apple size={28} className="mb-3 text-[#74e1c6]" /><div className="text-xs font-extrabold text-[#dcefee]">لم تحلل طعاماً بعد</div><div className="mt-1 text-[10px] text-slate-400">ستظهر هنا السعرات والبدائل الصحية</div></div>}</div></div><div className="mt-6 grid gap-4 md:grid-cols-3">{foodGroups.map(group => { const Icon = group.icon; return <div key={group.title} className="glass p-5"><div className="mb-4 flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-[14px]" style={{ background: group.bg, color: group.color }}><Icon size={18} /></div><h3 className="text-sm font-extrabold text-[#dcefee]">{group.title}</h3></div><ul className="space-y-3">{group.items.map(item => <li key={item} className="flex items-center gap-2 text-xs text-slate-400"><span className="h-1.5 w-1.5 rounded-full" style={{ background: group.color }} />{item}</li>)}</ul></div>; })}</div><div className="mt-6 rounded-[16px] border border-[#d6ebe8]/20 bg-[#74e1c6]/10 p-4 text-[10px] leading-5 text-slate-300"><ShieldCheck size={17} className="ml-1 inline text-[#74e1c6]" /> السعرات والكربوهيدرات تقديرية ولا تستبدل خطة اختصاصي التغذية.</div></div>; }\n\nfunction NutritionMetric({ label, value, unit, icon: Icon, color }: any) { return <div className="glass p-4"><div className="flex items-center justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-[14px]" style={{ background: `${color}22`, color }}><Icon size={18} /></div><span className="text-[10px] text-slate-400">اليوم</span></div><div className="mt-4 font-mono text-2xl font-bold text-[#dcefee]">{Math.round(value || 0)} <span className="font-sans text-[10px] text-slate-400">{unit}</span></div><div className="mt-1 text-[10px] font-bold" style={{ color }}>{label}</div></div>; }\n'''
