# replace settings function block
start=s.index('function SettingsSection(')
end=s.index('\nfunction SettingRow', start)
settings='''function SettingsSection({ settings, setSettings, water, setWater, profile, setProfile, healthResult, healthLoading, onHealthAnalysis, nutrition, onLogin, onExport }: any) { const toggle = (key: string) => setSettings({ ...settings, [key]: !settings[key] }); const setProfileField = (key: string, value: any) => setProfile({ ...profile, [key]: value }); const conditions = ["فقر الدم / نقص الحديد", "الربو", "الحساسية", "الغدة الدرقية", "أمراض القلب", "أمراض الكلى", "لا يوجد"]; const routines = ["صعود الدرج", "المشي للعمل", "الركض", "تمارين رياضية", "الأعمال المنزلية", "نشاط مكتبي"]; return <div className="fade-up"><SectionTitle eyebrow="تحكم كامل" title="الإعدادات والملف الصحي" detail="أجب عن الأسئلة الصحية ليقترح الذكاء الاصطناعي حركة واقعية وآمنة." /><div className="grid gap-6 lg:grid-cols-[1.15fr_.85fr]"><div className="glass p-6"><h3 className="mb-5 flex items-center gap-2 text-sm font-extrabold text-[#dcefee]"><Brain size={18} className="text-[#74e1c6]" /> بيانات التحليل الصحي</h3><div className="grid gap-4 sm:grid-cols-2"><ProfileInput label="العمر" value={profile.age} suffix="سنة" onChange={(v: string) => setProfileField("age", v)} /><ProfileInput label="الطول" value={profile.height} suffix="سم" onChange={(v: string) => setProfileField("height", v)} /><ProfileInput label="الوزن" value={profile.weight} suffix="كغ" onChange={(v: string) => setProfileField("weight", v)} /><SelectField label="الجنس" value={profile.gender} options={["أنثى", "ذكر", "أفضل عدم القول"]} onChange={(v: string) => setProfileField("gender", v)} /><SelectField label="فصيلة الدم" value={profile.bloodType} options={["غير معروف", "A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"]} onChange={(v: string) => setProfileField("bloodType", v)} /><SelectField label="النشاط العام" value={profile.activity} options={["قليل", "خفيف", "متوسط", "كثيف"]} onChange={(v: string) => setProfileField("activity", v)} /></div><div className="mt-5"><label className="mb-2 block text-[11px] font-bold text-slate-400">الحالات الصحية أو الاحتياطات</label><div className="flex flex-wrap gap-2">{conditions.map(item => <button key={item} onClick={() => setProfileField("conditions", (profile.conditions || []).includes(item) ? profile.conditions.filter((x: string) => x !== item) : [...(profile.conditions || []).filter((x: string) => x !== "لا يوجد" && item !== "لا يوجد"), item])} className={`rounded-full border px-3 py-2 text-[10px] font-bold ${(profile.conditions || []).includes(item) ? "border-[#74e1c6] bg-[#74e1c6]/15 text-[#a9ebdb]" : "border-white/10 text-slate-400"}`}>{item}</button>)}</div></div><div className="mt-5"><label className="mb-2 block text-[11px] font-bold text-slate-400">ما الذي تفعله خلال يومك؟</label><div className="flex flex-wrap gap-2">{routines.map(item => <button key={item} onClick={() => setProfileField("routines", (profile.routines || []).includes(item) ? profile.routines.filter((x: string) => x !== item) : [...(profile.routines || []), item])} className={`rounded-full border px-3 py-2 text-[10px] font-bold ${(profile.routines || []).includes(item) ? "border-[#f5b85f] bg-[#f5b85f]/15 text-[#f5d59b]" : "border-white/10 text-slate-400"}`}>{item}</button>)}</div></div><button onClick={onHealthAnalysis} disabled={healthLoading} className="mt-6 flex w-full items-center justify-center gap-2 rounded-[14px] bg-[#74e1c6] py-3 text-xs font-extrabold text-[#092b34] disabled:opacity-50">{healthLoading ? "جارٍ تحليل ملفك…" : "حلّل ملفي واقترح تماريني"}<Sparkles size={16} /></button>{healthResult && <div className="mt-5 max-h-80 overflow-auto whitespace-pre-wrap rounded-[15px] border border-white/10 bg-white/[.05] p-4 text-xs leading-7 text-slate-300">{healthResult}</div>}<p className="mt-4 text-[10px] leading-5 text-slate-500">هذه توصيات تثقيفية وليست تشخيصاً. عند الربو أو فقر الدم أو أمراض القلب/الكلى، ناقش شدة التمرين مع الطبيب.</p></div><div className="space-y-4"><div className="glass p-6"><h3 className="mb-4 text-sm font-extrabold text-[#dcefee]">التذكيرات والنوم</h3><div className="space-y-3"><SettingRow title="تذكير قياس السكر" value={settings.glucoseReminder} onChange={(v: string) => setSettings({ ...settings, glucoseReminder: v })} enabled={settings.notifications} onToggle={() => toggle("notifications")} /><SettingRow title="تذكير الدواء" value={settings.medicineReminder} onChange={(v: string) => setSettings({ ...settings, medicineReminder: v })} enabled={settings.notifications} onToggle={() => toggle("notifications")} /></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><ProfileInput label="وقت النوم" value={settings.bedtime} suffix="" onChange={(v: string) => setSettings({ ...settings, bedtime: v })} /><ProfileInput label="الاستيقاظ" value={settings.wake} suffix="" onChange={(v: string) => setSettings({ ...settings, wake: v })} /></div></div><div className="glass p-6"><div className="mb-4 flex items-center gap-3"><Trophy size={20} className="text-[#f5b85f]" /><h3 className="text-sm font-extrabold text-[#dcefee]">مكافآتك الصحية</h3></div><div className="grid grid-cols-2 gap-3"><BadgeCard icon="💧" title="مرطّب" done={water.consumed >= water.target * 8} detail="هدف الماء" /><BadgeCard icon="🏃" title="متحرّك" done={profile.routines?.length >= 2} detail="روتين نشط" /><BadgeCard icon="🩸" title="متابع" done={true} detail="سجّل قياسات" /><BadgeCard icon="🥗" title="اختيار واعٍ" done={nutrition.meals >= 1} detail="حلّل وجبة" /></div></div><div className="glass p-6"><div className="mb-4 flex items-center gap-3"><UserRound size={18} className="text-[#74e1c6]" /><div><h3 className="text-sm font-extrabold text-[#dcefee]">الحساب والتقرير</h3><p className="text-[10px] text-slate-400">مزامنة اختيارية وتقرير للطبيب</p></div></div><button onClick={onLogin} className="mb-3 flex w-full items-center justify-center gap-2 rounded-[14px] bg-white py-3 text-xs font-extrabold text-[#17243d]"><span className="text-base font-bold text-[#4285f4]">G</span> تسجيل الدخول عبر Google</button><button onClick={onExport} className="flex w-full items-center justify-center gap-2 rounded-[14px] border border-[#74e1c6]/40 bg-[#74e1c6]/10 py-3 text-xs font-extrabold text-[#a9ebdb]"><FileDown size={15} /> تصدير سجل السكر PDF</button></div></div></div></div>; }\n\nfunction SelectField({ label, value, options, onChange }: any) { return <div><label className="mb-2 block text-[11px] font-bold text-slate-400">{label}</label><select value={value} onChange={e => onChange(e.target.value)} className="w-full rounded-[14px] border border-white/10 bg-white/[.06] px-3 py-3 text-xs font-semibold text-[#dcefee] outline-none">{options.map((option: string) => <option key={option}>{option}</option>)}</select></div>; }\nfunction BadgeCard({ icon, title, done, detail }: any) { return <div className={`rounded-[15px] border p-3 ${done ? "border-[#74e1c6]/30 bg-[#74e1c6]/10" : "border-white/10 bg-white/[.03] opacity-55"}`}><div className="text-xl">{icon}</div><div className="mt-2 text-[11px] font-extrabold text-[#dcefee]">{title}</div><div className="mt-1 text-[9px] text-slate-400">{done ? "تم الإنجاز" : detail}</div></div>; }\n'''
s=s[:start]+settings+s[end:]
p.write_text(s)
